-- Generated by scripts/build-ai-budget-stop-catalog.ts from executable declarations.
-- Bob is not told about money: drawing-stop guidance, resume notes and the two
-- drawing tool descriptions no longer mention budgets, allocations or figures.
-- The server still enforces the limits; the owner's next message about a paused
-- drawing renews them (bob.grant_drawing_budget). Deploy matching Bob functions
-- first. New immutable versions; pinned manifests stay unchanged.
begin;
do $budget_stop_catalog$
declare item jsonb; prompt_uuid uuid; version_uuid uuid; next_version integer; activation jsonb:='{}'; current_version shared.ai_prompt_versions;
begin
 perform pg_advisory_xact_lock(hashtextextended('ai_catalog:bob',0));
 for item in select value from jsonb_array_elements($ai_catalog_patch$[
 {
  "key": "bob.frame.outstanding",
  "kind": "instruction_fragment",
  "label": "bob.frame.outstanding",
  "description": "",
  "content": "Outstanding drawing requests (private working state, not verified project truth). Resume the matching request_id after complements; do not restart or duplicate follow-up tasks. A request that paused at a limit continues on the owner's next message about it: call design_project_cad with that request_id at once. Do not read requests or sources first.\\n",
  "definition": {},
  "metadata": {
   "migrated_from": "supabase/functions/_shared/project-answer.ts",
   "label": "bob.frame.outstanding",
   "description": "",
   "publication": "budget-stop-no-ledger-v1"
  },
  "variables": []
 },
 {
  "key": "feedback.bob-budget-stop.resume.eefd1193bc73",
  "kind": "instruction_fragment",
  "label": "feedback.bob-budget-stop.resume.eefd1193bc73",
  "description": "",
  "content": "This drawing paused at a limit. Tell the owner plainly and finish this reply; do not read requests or sources to look for a way around it. The owner's next message about this drawing continues it: call design_project_cad at once with this same request_id, brief and handoff.",
  "definition": {},
  "metadata": {
   "migrated_from": "supabase/functions/_shared/bob-budget-stop.ts",
   "label": "feedback.bob-budget-stop.resume.eefd1193bc73",
   "description": "",
   "publication": "budget-stop-no-ledger-v1",
   "source_field": "budgetResumeAction"
  },
  "variables": []
 },
 {
  "key": "feedback.bob-budget-stop.resume.51aac0199a6c",
  "kind": "instruction_fragment",
  "label": "feedback.bob-budget-stop.resume.51aac0199a6c",
  "description": "",
  "content": "This turn's work limit is reached. Tell the owner what exists and that the next message continues this same request_id; do not retry in this turn.",
  "definition": {},
  "metadata": {
   "migrated_from": "supabase/functions/_shared/bob-budget-stop.ts",
   "label": "feedback.bob-budget-stop.resume.51aac0199a6c",
   "description": "",
   "publication": "budget-stop-no-ledger-v1",
   "source_field": "budgetResumeAction"
  },
  "variables": []
 },
 {
  "key": "feedback.bob-budget-stop.resume.bca602f7146a",
  "kind": "instruction_fragment",
  "label": "feedback.bob-budget-stop.resume.bca602f7146a",
  "description": "",
  "content": "This drawing paused and the exact cause is not available. Tell the owner the drawing is paused and finish this reply; do not retry in this turn. It continues on a later message about it.",
  "definition": {},
  "metadata": {
   "migrated_from": "supabase/functions/_shared/bob-budget-stop.ts",
   "label": "feedback.bob-budget-stop.resume.bca602f7146a",
   "description": "",
   "publication": "budget-stop-no-ledger-v1",
   "source_field": "budgetResumeAction"
  },
  "variables": []
 },
 {
  "key": "feedback.bob-budget-stop.resume.9c3a74e182d5",
  "kind": "instruction_fragment",
  "label": "feedback.bob-budget-stop.resume.9c3a74e182d5",
  "description": "",
  "content": "A previous step of this drawing is still being settled. Tell the owner the drawing is paused and finish this reply; do not retry in this turn. It continues on a later message about it.",
  "definition": {},
  "metadata": {
   "migrated_from": "supabase/functions/_shared/bob-budget-stop.ts",
   "label": "feedback.bob-budget-stop.resume.9c3a74e182d5",
   "description": "",
   "publication": "budget-stop-no-ledger-v1",
   "source_field": "budgetResumeAction"
  },
  "variables": []
 },
 {
  "key": "feedback.bob-budget-stop.resume.f0e268bdddc1",
  "kind": "instruction_fragment",
  "label": "feedback.bob-budget-stop.resume.f0e268bdddc1",
  "description": "",
  "content": "Restore the same request through its existing context-recovery path. Do not create a new request.",
  "definition": {},
  "metadata": {
   "migrated_from": "supabase/functions/_shared/bob-budget-stop.ts",
   "label": "feedback.bob-budget-stop.resume.f0e268bdddc1",
   "description": "",
   "publication": "budget-stop-no-ledger-v1",
   "source_field": "budgetResumeAction"
  },
  "variables": []
 },
 {
  "key": "feedback.bob-budget-stop.resume.f43f67fe832d",
  "kind": "instruction_fragment",
  "label": "feedback.bob-budget-stop.resume.f43f67fe832d",
  "description": "",
  "content": "Design work reached this turn's limit before review. Review or deliver what exists; do not dispatch more design work in this turn.",
  "definition": {},
  "metadata": {
   "migrated_from": "supabase/functions/_shared/bob-budget-stop.ts",
   "label": "feedback.bob-budget-stop.resume.f43f67fe832d",
   "description": "",
   "publication": "budget-stop-no-ledger-v1",
   "source_field": "budgetResumeAction"
  },
  "variables": []
 },
 {
  "key": "feedback.cad-assistant.next-action.9c82aa7ab11b",
  "kind": "instruction_fragment",
  "label": "feedback.cad-assistant.next-action.9c82aa7ab11b",
  "description": "",
  "content": "Continue design_project_cad with this existing request_id. Reuse its work and gaps; do not create another request.",
  "definition": {},
  "metadata": {
   "migrated_from": "supabase/functions/_shared/cad-assistant.ts",
   "label": "feedback.cad-assistant.next-action.9c82aa7ab11b",
   "description": "",
   "publication": "budget-stop-no-ledger-v1",
   "source_field": "next-action"
  },
  "variables": []
 },
 {
  "key": "feedback.cad-assistant.next-action.cb389635c1a3",
  "kind": "instruction_fragment",
  "label": "feedback.cad-assistant.next-action.cb389635c1a3",
  "description": "",
  "content": "Continue design_project_cad with this same request_id and the returned brief/handoff. Fresh current-source intake is required; unknowns stay unknown.",
  "definition": {},
  "metadata": {
   "migrated_from": "supabase/functions/_shared/cad-assistant.ts",
   "label": "feedback.cad-assistant.next-action.cb389635c1a3",
   "description": "",
   "publication": "budget-stop-no-ledger-v1",
   "source_field": "next-action"
  },
  "variables": []
 }
]$ai_catalog_patch$::jsonb) loop
  select id into prompt_uuid from shared.ai_prompts where app='bob' and prompt_key=item->>'key' and definition_kind=item->>'kind' for update;
  if prompt_uuid is null then raise exception 'budget_stop_catalog_definition_missing'; end if;
  select v.* into current_version from shared.ai_prompts p join shared.ai_prompt_versions v on v.id=p.active_version_id where p.id=prompt_uuid;
  select coalesce(max(version),0)+1 into next_version from shared.ai_prompt_versions where prompt_id=prompt_uuid;
  insert into shared.ai_prompt_versions(prompt_id,version,definition_kind,definition_format_version,metadata,content,definition,flow,available_variables)
   values(prompt_uuid,next_version,item->>'kind',1,(current_version.metadata-'seed_version'-'source_revision')||item->'metadata',item->>'content',current_version.definition,current_version.flow,current_version.available_variables) returning id into version_uuid;
  activation:=activation||jsonb_build_object(item->>'key',version_uuid::text);
 end loop;
 for item in select value from jsonb_array_elements($budget_stop_contracts$[
 {
  "key": "tools.design_project_cad",
  "description": "Delegate a requested CAD drawing from the current selected Solution and its purpose-specific design intent. Resolve consequential choices through expert advice and supported selections before fixing construction geometry; reuse prior decisions and delegation. An exploratory form sketch may retain explicitly deferred choices within its stated scope. For a construction concept with parts, material revisions and typed joints, use save_construction_draft and check_construction_draft first; this drawing tool cannot replace that deliverable or repair catalog definitions. Selected original images accompany the same pinned intent for designer and reviewer. Intake returns remaining needs together; reuse existing Tasks/Steps or gather measurements in chat, then resume the same request_id. Returns a checked candidate, not a saved drawing. Specify coordinate/view directions and relevant object IDs; the assistant can fetch wider dependencies.",
  "parameters": {
   "type": "object",
   "additionalProperties": false,
   "properties": {
    "request_id": {
     "type": [
      "string",
      "null"
     ],
     "description": "Copy the saved drawing request ID to resume after complements. Null only for a new request. With an ID, pass handoff:null and requirement_changes:[] to reuse ALL saved requirements. When the owner writes again about a request that paused at a limit, call this immediately with that ID and it continues. Do not re-read requests or sources first."
    },
    "brief": {
     "type": "string"
    },
    "handoff": {
     "anyOf": [
      {
       "type": "object",
       "additionalProperties": false,
       "properties": {
        "deliverable": {
         "type": "string",
         "minLength": 1,
         "maxLength": 2000
        },
        "requirements": {
         "type": "array",
         "minItems": 1,
         "maxItems": 24,
         "items": {
          "type": "object",
          "additionalProperties": false,
          "properties": {
           "requirement": {
            "type": "string",
            "minLength": 1,
            "maxLength": 2000
           },
           "basis": {
            "type": "string",
            "enum": [
             "user_request",
             "project_record",
             "working_assumption"
            ]
           },
           "source_ref": {
            "type": [
             "string",
             "null"
            ],
            "maxLength": 500
           }
          },
          "required": [
           "requirement",
           "basis",
           "source_ref"
          ]
         }
        },
        "coordinates": {
         "type": "object",
         "additionalProperties": false,
         "properties": {
          "origin": {
           "type": [
            "string",
            "null"
           ],
           "maxLength": 500
          },
          "positive_x": {
           "type": [
            "string",
            "null"
           ],
           "maxLength": 500
          },
          "positive_y": {
           "type": [
            "string",
            "null"
           ],
           "maxLength": 500
          },
          "positive_z": {
           "type": [
            "string",
            "null"
           ],
           "maxLength": 500
          }
         },
         "required": [
          "origin",
          "positive_x",
          "positive_y",
          "positive_z"
         ]
        },
        "views": {
         "type": "array",
         "minItems": 1,
         "maxItems": 4,
         "uniqueItems": true,
         "items": {
          "type": "string",
          "enum": [
           "front",
           "right",
           "top",
           "isometric"
          ]
         }
        },
        "unresolved": {
         "type": "array",
         "maxItems": 20,
         "items": {
          "type": "string",
          "minLength": 1,
          "maxLength": 2000
         }
        }
       },
       "required": [
        "deliverable",
        "requirements",
        "coordinates",
        "views",
        "unresolved"
       ]
      },
      {
       "type": "null"
      }
     ],
     "description": "New request only: transfer owner requirements without IDs; the server creates and persists their identities. Map coordinates and views, keep unknown directions null and cite exact source refs. Resume with null: the server reads the saved handoff, including earlier corrections. Use requirement_changes only for explicit additions or changes."
    },
    "requirement_changes": {
     "type": "array",
     "maxItems": 24,
     "description": "Explicit changes to a saved request only. Empty to resume. Copy requirement_id from the saved handoff to update it; null only for a genuinely new requirement. Never invent an ID. Earlier requirements are retained.",
     "items": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
       "requirement_id": {
        "type": [
         "string",
         "null"
        ],
        "maxLength": 40
       },
       "requirement": {
        "type": "string",
        "minLength": 1,
        "maxLength": 2000
       },
       "basis": {
        "type": "string",
        "enum": [
         "user_request",
         "project_record",
         "working_assumption"
        ]
       },
       "source_ref": {
        "type": [
         "string",
         "null"
        ],
        "maxLength": 500
       }
      },
      "required": [
       "requirement_id",
       "requirement",
       "basis",
       "source_ref"
      ]
     }
    },
    "area_id": {
     "type": [
      "string",
      "null"
     ]
    },
    "component_id": {
     "type": [
      "string",
      "null"
     ]
    },
    "step_id": {
     "type": [
      "string",
      "null"
     ],
     "description": "Current work Step this drawing supports; read the plan and pass its exact ID when relevant. Null for a project-wide drawing. Planning is a phase."
    },
    "artifact_id": {
     "type": [
      "string",
      "null"
     ],
     "description": "Exact existing construction checkpoint to draw, or CAD Artifact to revise. A construction is freshly checked and rendered verbatim into a separate linked concept drawing; it is never redesigned here. Null only when no existing construction applies."
    },
    "construction_revision": {
     "type": [
      "integer",
      "null"
     ],
     "minimum": 1,
     "maximum": 999999999,
     "description": "For construction rendering, copy the exact revision from its saved/read receipt. The server reads and checks that version; it cannot substitute the newest design. Resume preserves the saved version. Null only for a CAD drawing without a construction source."
    }
   },
   "required": [
    "request_id",
    "brief",
    "handoff",
    "requirement_changes",
    "area_id",
    "component_id",
    "step_id",
    "artifact_id",
    "construction_revision"
   ]
  }
 },
 {
  "key": "tools.restore_drawing_request",
  "description": "Restore your paused request from ALL canonical requirements of a current approved plan Step and the current owner instruction. Read request and plan first. Keeps the same ID; starts fresh intake without recovering deleted chat. Then call design_project_cad with that ID and preserve the restored requirements. Does not grant readiness.",
  "parameters": {
   "type": "object",
   "additionalProperties": false,
   "properties": {
    "request_id": {
     "type": "string"
    },
    "expected_revision": {
     "type": "integer",
     "minimum": 0
    },
    "plan_revision": {
     "type": "integer",
     "minimum": 1
    },
    "step_id": {
     "type": "string"
    },
    "request_quote": {
     "type": "string",
     "maxLength": 500
    }
   },
   "required": [
    "request_id",
    "expected_revision",
    "plan_revision",
    "step_id",
    "request_quote"
   ]
  }
 }
]$budget_stop_contracts$::jsonb) loop
  select id into prompt_uuid from shared.ai_prompts where app='bob' and prompt_key=item->>'key' and definition_kind='tool_contract' for update;
  if prompt_uuid is null then raise exception 'budget_stop_catalog_contract_missing'; end if;
  select v.* into current_version from shared.ai_prompts p join shared.ai_prompt_versions v on v.id=p.active_version_id where p.id=prompt_uuid;
  select coalesce(max(version),0)+1 into next_version from shared.ai_prompt_versions where prompt_id=prompt_uuid;
  insert into shared.ai_prompt_versions(prompt_id,version,definition_kind,definition_format_version,metadata,content,definition,flow,available_variables)
   values(prompt_uuid,next_version,current_version.definition_kind,current_version.definition_format_version,(current_version.metadata-'seed_version'-'source_revision')||jsonb_build_object('publication','budget-stop-no-ledger-v1'),current_version.content,current_version.definition||jsonb_build_object('description',item->>'description','parameters',item->'parameters','required_parameters',item#>'{parameters,required}','optional_parameters','[]'::jsonb),current_version.flow,current_version.available_variables) returning id into version_uuid;
  activation:=activation||jsonb_build_object(item->>'key',version_uuid::text);
 end loop;
 perform shared.activate_ai_catalog('bob',activation);
end $budget_stop_catalog$;
commit;
